from pathlib import Path
import hashlib,json
p=Path('studies/mean_field_peeling/three_sample_near_identity_all_depths')
files=['CONTRACT.md','REPORT.md','INITIALIZATION.md','NECESSARY_FITTING_SCALE.md','SOURCE_ROUTE.md','ENERGY_GALERKIN_ROUTE.md']
h={f:hashlib.sha256((p/f).read_bytes()).hexdigest() for f in files}
(p/'MATHEMATICAL_HASHES.json').write_text(json.dumps(h,indent=2)+'\\n')
checks={}
for f in ['reviews/SOURCE_PARTIAL_REVIEW.md','reviews/LIMITS_PARTIAL_REVIEW.md']:
    s=(p/f).read_text()
    checks[f]={k:h[k] in s for k in ['INITIALIZATION.md','NECESSARY_FITTING_SCALE.md']}
print(json.dumps({'hashes':h,'review_version_checks':checks},indent=2))
PY"
